def getProviderLimits(self, provider):
    cloud_quota = self.api.nodes_cache.getQuota(provider, include_requested=False)
    provider_resource_limits = self.api.nodes_cache.getProviderResourceLimits(provider)
    other_endpoint_usage = self._getOtherEndpointUsage(provider)
    return min(cloud_quota, provider_resource_limits) - other_endpoint_usage - self._getThisProviderUsage(provider)

def _getOtherEndpointUsage(self, provider):
    other_endpoint_usage = 0
    for other_provider in self.api.nodes_cache.getProviders():
        if other_provider != provider:
            other_endpoint_usage += self.api.nodes_cache.getQuota(other_provider)
    return other_endpoint_usage

def _getThisProviderUsage(self, provider):
    return self.api.nodes_cache.getQuota(provider, include_requested=True)

def doesProviderHaveQuotaForLabel(self, provider, label):
    provider_limits = self.getProviderLimits(provider)
    requested_nodes = self.api.nodes_cache.getRequestedNodes(provider, label)
    return provider_limits >= requested_nodes
